/bin/bash -lc "python - <<'PY'
from pathlib import Path
from openpyxl import load_workbook
for p in [Path('inputs/230214_Schenz_et_al_2022_CHIP_Genes.xlsx'),Path('inputs/230215_Trio_Status.xlsx'),Path('inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_179-P1.xlsx')]:
    wb=load_workbook(p,read_only=True,data_only=True)
    print(p.name, wb.sheetnames)
    for ws in wb.worksheets:
        print(' ',ws.title,ws.max_row,ws.max_column)
        for row in ws.iter_rows(min_row=1,max_row=min(4,ws.max_row),values_only=True): print('   ',row)
PY"

